package main

import (
	"fmt"
	"go/doc/comment"
	"reflect"
)

func main() {
	p := &comment.Parser{
		LookupPackage: func(name string) (string, bool) { return name, true },
		LookupSym:     func(recv, name string) bool { return true },
	}
	cases := []string{
		"[Foo] [foo] [Foo.Bar] [pkg.Foo] [pkg.Foo.Bar] [math] [math.Sin] [net/http] [foo bar] [Foo-Bar] [Foo.Bar.Baz]",
		"[int] [string] [error] [len] [nil] [true]",
	}
	for _, text := range cases {
		d := p.Parse("// " + text)
		fmt.Println("TEXT:", text)
		walk(d.Content, 0)
		fmt.Println()
	}
}

func walk(blocks []comment.Block, depth int) {
	for _, b := range blocks {
		fmt.Printf("%*sblock %T\n", depth*2, "", b)
		switch b := b.(type) {
		case *comment.Paragraph:
			walkText(b.Text, depth+1)
		case *comment.Heading:
			walkText(b.Text, depth+1)
		case *comment.List:
			for _, item := range b.Items {
				walk(item.Content, depth+1)
			}
		}
	}
}

func walkText(ts []comment.Text, depth int) {
	for _, t := range ts {
		switch t := t.(type) {
		case *comment.DocLink:
			fmt.Printf("%*sDocLink Text=%v ImportPath=%q Recv=%q Name=%q\n", depth*2, "", t.Text, t.ImportPath, t.Recv, t.Name)
		case *comment.Link:
			fmt.Printf("%*sLink URL=%q Text=%v\n", depth*2, "", t.URL, t.Text)
		case comment.Plain:
			fmt.Printf("%*sPlain %q\n", depth*2, "", string(t))
		case comment.Italic:
			fmt.Printf("%*sItalic %q\n", depth*2, "", string(t))
		default:
			fmt.Printf("%*sUNKNOWN %T %v\n", depth*2, "", t, t)
		}
	}
}

